('anac', '99e375fe-e860-4cbd-a48f-ac5e28c8c574', 'Legislação Aeronáutica', null, 'COM RELAÇÃO À DURAÇÃO DO TRABALHO DOS TRIPULANTES, ASSINALE A ALTERNATIVA CORRETA:', null, '[{"letra": "A", "texto": "OS LIMITES SEMANAIS E MENSAIS DE TRABALHO PODERÃO SER ALTERADOS MEDIANTE ACORDO OU CONVENÇÃO COLETIVA DE TRABALHO", "imagem_url": null}, {"letra": "B", "texto": "NÃO SERÃO COMPUTADOS OS TEMPOS DE RESERVA E SOBREAVISO NA DURAÇÃO DO TRABALHO DOS TRIPULANTES DE VOO E DE CABINE", "imagem_url": null}, {"letra": "C", "texto": "PARA QUE O DESLOCAMENTO COMO TRIPULANTE EXTRA A SERVIÇO ESTEJA PREVISTA NA DURAÇÃO DO TRABALHO, ESTE DEVERÁ ESTAR PREVISTO NA ESCALA DO TRIPULANTE COM 30 DIAS DE ANTECEDÊNCIA", "imagem_url": null}, {"letra": "D", "texto": "OS TRIPULANTES QUE TAMBÉM EXERÇAM ATIV ADMINISTRATIVAS TERÃO OS LIMITES DE SUA JORNADA DEFINIDOS EM CONVENÇÃO OU ACORDO COLETIVO, DESDE QUE NÃO ULTRAPASSEM OS PARÂM ESTABELECIDOS NA REGULAMENTAÇÃO", "imagem_url": null}]'::jsonb, 'D', null),
