('anac', 'a4da51f4-9969-469d-bc77-8dc61a9abd3d', 'Primeiros Socorros', null, 'UMA VÍTIMA APRESENTA-SE DEITADA NO LOCAL DO ACIDENTE E OBSERVA-SE SAÍDA DE SANGUE PELO OUVIDO. NA PALPAÇÃO CONSTATA-SE SINAIS DE AFUNDAMENTO CRANIANO. A CONDUTA DO COMISSÁRIO É:', null, '[{"letra": "A", "texto": "imobilizar com faixas, deixando o sangue do ouvido sair livremente e jejum", "imagem_url": null}, {"letra": "B", "texto": "enfaixar a cabeça em forma de coroa de noiva, deixar o indivíduo tranqüilo e comprimir os locais que sangram", "imagem_url": null}, {"letra": "C", "texto": "imobilizar a cabeça com atadura triangular, mas levando em conta que em primeiro lugar devemos tratar as hemorragias do ouvido", "imagem_url": null}, {"letra": "D", "texto": "enfaixar a cabeça com atadura larga e compressiva, impedindo primeiro a saída de sangue pelo ouvido", "imagem_url": null}]'::jsonb, 'A', null),
