('anac', 'bc6cd6ac-4bb2-4de2-9eec-e1e31288b943', 'Segurança e Emergência', null, 'PARA ABRIR UMA SAÍDA DE EMERGÊNCIA SOBRE A ASA, PELO LADO DE FORA, DEVE-SE:', null, '[{"letra": "A", "texto": "puxar o comando superior da janela para baixo", "imagem_url": null}, {"letra": "B", "texto": "puxar o comando inferior para baixo", "imagem_url": null}, {"letra": "C", "texto": "pressionar o retângulo acima do visor da janela para dentro", "imagem_url": null}, {"letra": "D", "texto": "NDA", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'bc6fe0b0-9c9e-44d3-8784-4fae352d5d38', 'Primeiros Socorros', null, 'OCORRENDO UM PARTO DE EMERGÊNCIA A BORDO, CASO A PLACENTA NÃO SEJA EXPULSA NO TEMPO PREVISTO, MESMO APÓS AS MASSAGENS ABDOMINAIS, DEVE-SE', null, '[{"letra": "A", "texto": "CHAMAR O CHEFE DE CABINE", "imagem_url": null}, {"letra": "B", "texto": "OBSERVAR E AGUARDAR", "imagem_url": null}, {"letra": "C", "texto": "PUXAR COM A MÃO COBERTA POR LUVA", "imagem_url": null}, {"letra": "D", "texto": "TRACIONAR A PLACENTA PELO CORDÃO UMBILICAL", "imagem_url": null}]'::jsonb, 'B', null),
