('anac', 'bcb1f708-ae15-402d-a350-6831a344f5a9', 'Conhecimentos Técnicos', null, 'O AR QUE COMPÕE A ATMOSFERA É UMA MISTURA MECÂNICA DE GASES, NA SEGUINTE PROPORÇÃO:', null, '[{"letra": "A", "texto": "nitrogênio 21%; oxigênio 78%; outros gases 1%", "imagem_url": null}, {"letra": "B", "texto": "nitrogênio 21%; oxigênio 1%; outros gases 78%", "imagem_url": null}, {"letra": "C", "texto": "nitrogênio 1%; oxigênio 21%; outros gases 78%", "imagem_url": null}, {"letra": "D", "texto": "nitrogênio 78%; oxigênio 21%; outros gases 1%", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'bcbfbee0-132c-4ad7-9723-774772f8d3ae', 'Legislação Aeronáutica', null, 'COM RELAÇÃO AOS PERÍODOS DE REPOUSO, ASSINALE A ALTERNATIVA CORRETA:', null, '[{"letra": "A", "texto": "NÃO HAVERÁ NENHUM TIPO DE RESSARCIMENTO AO TRIPULANTE QUE CUSTEAR TRANSPORTE ENTRE O AEROPORTO E O LOCAL DE REPOUSO", "imagem_url": null}, {"letra": "B", "texto": "ENTENDE-SE POR ACOMODAÇÃO ADEQUADA, QUARTOS INDIVIDUAIS EM HOSPEDAGEM DE LUXO COM BANHEIRO COMPARTILHADO OU PRIVATIVO", "imagem_url": null}, {"letra": "C", "texto": "O TEMPO MÍNIMO DE REPOUSO TERÁ DURAÇÃO DE 6 HORAS", "imagem_url": null}, {"letra": "D", "texto": "É ASSEGURADO AO TRIPULANTE, FORA DE SUA BASE CONTRATUAL ACOMODAÇÃO ADEQUADA PARA REPOUSO E TRANSPORTE ENTRE O AEROPORTO E O LOCAL DE REPOUSO", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'bcd4d365-9d4b-40d9-bba9-b54f6d3c3db6', 'Segurança e Emergência', null, 'SE DURANTE UMA EVACUAÇÃO, AO OLHAR O VISOR, O COMISSÁRIO PERCEBER QUE HÁ FOGO, O PROCEDIMENTO CORRETO PARA ESTA SITUAÇÃO SERÁ:', null, '[{"letra": "A", "texto": "abandonar a saída e reorientar para outras saídas operativas", "imagem_url": null}, {"letra": "B", "texto": "fechar a porta, abandonar a saída e reorientar para outras saídas", "imagem_url": null}, {"letra": "C", "texto": "não abrir a porta, permanecer junto a ela, gritando FOGO e reorientar para outras saídas", "imagem_url": null}, {"letra": "D", "texto": "abre a porta e comanda a evacuação", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'bce9495c-ed00-4211-aea3-4aff62b096be', 'Conhecimentos Técnicos', null, 'A QUANTIDADE DE ENERGIA SOLAR QUE ATINGE A SUPERFÍCIE TERRESTRE, APÓS SOFRER FILTRAGEM SELETIVA, É DENOMINADA', null, '[{"letra": "A", "texto": "reflexão", "imagem_url": null}, {"letra": "B", "texto": "albedo", "imagem_url": null}, {"letra": "C", "texto": "insolação", "imagem_url": null}, {"letra": "D", "texto": "difusão", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'bcf9f0ff-9c11-453d-9a6e-4b7d9f8d5c66', 'Legislação Aeronáutica', null, 'O PRINCÍPIO A SER OBSERVADO PELA ESCALA DE VOO DO AERONAUTA É O DO(A)', null, '[{"letra": "A", "texto": "AÇÃO", "imagem_url": null}, {"letra": "B", "texto": "RODÍZIO", "imagem_url": null}, {"letra": "C", "texto": "REVERSIBILIDADE", "imagem_url": null}, {"letra": "D", "texto": "EXTRATERRITORIALIDADE", "imagem_url": null}]'::jsonb, 'B', null),
