('anac', 'c3be27df-67b7-4079-bade-096c0d23ef59', 'Segurança e Emergência', null, 'O MOMENTO PROPÍCIO PARA SE SINALIZAR COM O FOGUETE PIROTÉCNICO, CORANTE MARCADOR DE ÁGUA E ESPELHO É', null, '[{"letra": "A", "texto": "TANTO À NOITE QUANTO DE DIA", "imagem_url": null}, {"letra": "B", "texto": "AO SER AVISTADA AERONAVE OU EMBARCAÇÃO, OU FOR OUVIDO O RUÍDO DE MOTORES", "imagem_url": null}, {"letra": "C", "texto": "DENTRO DOS HORÁRIOS INTERNACIONAIS DE SILÊNCIO", "imagem_url": null}, {"letra": "D", "texto": "À NOITE", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'c3e40b4c-6674-45f6-a809-0dd25164cba8', 'Legislação Aeronáutica', null, 'CONFORME O RBHA-63, PARA A OBTENÇÃO DA LICENÇA DE COMISSÁRIO, A ANAC EXIGE O CUMPRIMENTO DE ALGUNS PRÉ REQUISITOS, ENTRE ESTES, TÊM SE:', null, '[{"letra": "A", "texto": "conclusão do curso superior", "imagem_url": null}, {"letra": "B", "texto": "estágio em empresa homologada", "imagem_url": null}, {"letra": "C", "texto": "instrução prática de, no mínimo, 14 horas de voo", "imagem_url": null}, {"letra": "D", "texto": "frequência obrigatória em curso na área de segurança de voo", "imagem_url": null}]'::jsonb, 'C', null),
