('anac', 'c3f48a1f-0576-4d49-8afb-3b302332fa8e', 'Legislação Aeronáutica', null, 'HORA DE VOO OU TEMPO PARA AERONAVE DE ASA FIXA, É O PERÍODO COMPREENDIDO ENTRE:', null, '[{"letra": "A", "texto": "ligar e desligar motores", "imagem_url": null}, {"letra": "B", "texto": "início do deslocamento, com fins de decolagem, até o estacionamento, quando o término do voo (calço a calço)", "imagem_url": null}, {"letra": "C", "texto": "partida dos motores e estacionamento da mesma ao tempo do voo", "imagem_url": null}, {"letra": "D", "texto": "decolagem e pouso", "imagem_url": null}]'::jsonb, 'B', null),
