-- Cabin Crew · Questões da banca ANAC · parte 3 de 4
-- Gerado a partir dos CSVs exportados da Horsky. Pode rodar mais de uma vez (atualiza, não duplica).

on conflict (banco, origem_id) do update set categoria = excluded.categoria, contexto = excluded.contexto, enunciado = excluded.enunciado,
  imagem_url = excluded.imagem_url, alternativas = excluded.alternativas, correta = excluded.correta, explicacao = excluded.explicacao;

on conflict (banco, origem_id) do update set categoria = excluded.categoria, contexto = excluded.contexto, enunciado = excluded.enunciado,
  imagem_url = excluded.imagem_url, alternativas = excluded.alternativas, correta = excluded.correta, explicacao = excluded.explicacao;

on conflict (banco, origem_id) do update set categoria = excluded.categoria, contexto = excluded.contexto, enunciado = excluded.enunciado,
  imagem_url = excluded.imagem_url, alternativas = excluded.alternativas, correta = excluded.correta, explicacao = excluded.explicacao;

on conflict (banco, origem_id) do update set categoria = excluded.categoria, contexto = excluded.contexto, enunciado = excluded.enunciado,
  imagem_url = excluded.imagem_url, alternativas = excluded.alternativas, correta = excluded.correta, explicacao = excluded.explicacao;

on conflict (banco, origem_id) do update set categoria = excluded.categoria, contexto = excluded.contexto, enunciado = excluded.enunciado,
  imagem_url = excluded.imagem_url, alternativas = excluded.alternativas, correta = excluded.correta, explicacao = excluded.explicacao;

update questoes set ativo = (correta is not null and jsonb_array_length(alternativas) >= 2) where origem_id is not null;

select banco, count(*) filter (where ativo) as ativas, count(*) as total from questoes group by banco order by banco;
